// Native LAMMPS (stable 22Jul2025 update 6) as a shared library, driven from Python and from C. Recorded once.
// dump: float64 x y z vx vy vz for atoms 1..171 at steps 0, 50, ..., 200 (Python fix external run).
export const NATIVE = {"py": "import numpy as np, time\nfrom lammps import lammps\n\nBASE = \"\"\"\nunits           lj\natom_style      atomic\natom_modify     map array\nlattice         fcc 0.8442\nregion          box block 0 8 0 8 0 8\nregion          blob block 2.5 5.5 2.5 5.5 2.5 5.5\ncreate_box      1 box\ncreate_atoms    1 region blob\nmass            1 1.0\nvelocity        all create 1.0 87287 loop geom\npair_style      lj/cut 2.5\npair_coeff      1 1 1.0 1.0 2.5\nfix             1 all nve\n\"\"\"\nK = 5.0\nDUMP = \"\"\"\ndump            d all custom 50 {} id x y z vx vy vz\ndump_modify     d format float %.17g sort id\nthermo_style    custom step pe ke etotal f_2\nthermo_modify   format float %.17g\nthermo          50\n\"\"\"\n\n# A: the tether written in Python, called by LAMMPS every step through fix external\na = lammps(cmdargs=[\"-log\", \"none\", \"-screen\", \"none\", \"-nocite\"])\na.commands_string(BASE)\nn = a.get_natoms()\ntag0 = a.numpy.extract_atom(\"id\")[:n].copy()\nx0 = np.empty((n + 1, 3)); x0[tag0] = a.numpy.extract_atom(\"x\")[:n]   # reference positions by atom ID\ncalls = 0\ndef tether(lmp, ntimestep, nlocal, tag, x, fext):\n    global calls\n    calls += 1\n    dx = x - x0[tag]                      # numpy arrays: tag and x of the nlocal owned atoms\n    fext[:] = -(K * dx)                   # LAMMPS adds fext to f\n    lmp.fix_external_set_energy_global(\"2\", 0.5 * K * float((dx * dx).sum()))\na.command(\"fix 2 all external pf/callback 1 1\")\na.command(\"fix_modify 2 energy yes\")\na.set_fix_external_callback(\"2\", tether, a)\na.commands_string(DUMP.format(\"a.dump\"))\nt = time.perf_counter(); a.command(\"run 200\"); ta = time.perf_counter() - t\n\n# B: the same with LAMMPS's own fix spring/self\nb = lammps(cmdargs=[\"-log\", \"none\", \"-screen\", \"none\", \"-nocite\"])\nb.commands_string(BASE)\nb.command(f\"fix 2 all spring/self {K}\")\nb.command(\"fix_modify 2 energy yes\")\nb.commands_string(DUMP.format(\"b.dump\"))\nt = time.perf_counter(); b.command(\"run 200\"); tb = time.perf_counter() - t\n\nprint(\"atoms\", n, \"callbacks\", calls)\nfor name, lmp in ((\"python\", a), (\"spring/self\", b)):\n    print(name, \"pe %.17g  etotal %.17g\" % (lmp.get_thermo(\"pe\"), lmp.get_thermo(\"etotal\")))\nsame = open(\"a.dump\").read() == open(\"b.dump\").read()\nprint(\"dumps identical:\", same, \" time python %.3f s, built-in %.3f s\" % (ta, tb))\na.close(); b.close()\n", "pyout": "atoms 171 callbacks 201\npython pe -4.1107608974241341  etotal -3.3399392315507428\nspring/self pe -4.1107608974241341  etotal -3.3399392315507428\ndumps identical: True  time python 0.016 s, built-in 0.011 s\n", "c": "/* LAMMPS from C: create, run, read results, destroy. */\n#include \"library.h\"\n#include <stdio.h>\n\nint main(void)\n{\n  const char *args[] = {\"lmp\", \"-log\", \"none\", \"-screen\", \"none\", \"-nocite\"};\n  void *lmp = lammps_open_no_mpi(6, (char **) args, NULL);\n\n  lammps_commands_string(lmp,\n      \"units lj\\n atom_style atomic\\n lattice fcc 0.8442\\n\"\n      \"region box block 0 4 0 4 0 4\\n create_box 1 box\\n create_atoms 1 box\\n\"\n      \"mass 1 1.0\\n velocity all create 1.44 87287 loop geom\\n\"\n      \"pair_style lj/cut 2.5\\n pair_coeff 1 1 1.0 1.0 2.5\\n fix 1 all nve\\n run 100\");\n\n  double natoms = lammps_get_natoms(lmp);\n  double pe = lammps_get_thermo(lmp, \"pe\");\n  int nlocal = lammps_extract_setting(lmp, \"nlocal\");\n  double **x = (double **) lammps_extract_atom(lmp, \"x\");\n  double *pe_compute = (double *) lammps_extract_compute(lmp, \"thermo_pe\", LMP_STYLE_GLOBAL, LMP_TYPE_SCALAR);\n\n  printf(\"LAMMPS version %d, %.0f atoms, %d local\\n\", lammps_version(lmp), natoms, nlocal);\n  printf(\"pe per atom (thermo) %.17g, total (compute) %.17g\\n\", pe, *pe_compute);\n  printf(\"atom 0 at %.17g %.17g %.17g\\n\", x[0][0], x[0][1], x[0][2]);\n  lammps_close(lmp);\n  return 0;\n}\n", "cout": "LAMMPS version 20250722, 256 atoms, 256 local\npe per atom (thermo) -5.7150773689918557, total (compute) -1463.0598064619151\natom 0 at 0.19715824138088497 6.5069708102742494 0.074350011798647933\n", "n": 171, "steps": [0, 50, 100, 150, 200], "dump": ""};
